using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextHelper.CreateSeededContext();
        _controller = CreateController(_context);
    }

    private static InstructorsController CreateController(SchoolContext context)
    {
        var controller = new InstructorsController(context);
        controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        controller.TempData = new TempDataDictionary(
            controller.ControllerContext.HttpContext,
            new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        return controller;
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ---- Index Tests ----

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        // Act
        var result = _controller.Index(null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var viewModel = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Single(viewModel.Instructors);
        Assert.Equal("Abercrombie", viewModel.Instructors.First().LastName);
    }

    [Fact]
    public void Index_WithInstructorId_ShowsCourses()
    {
        // Arrange - add a course assignment
        var instructor = _context.Instructors.First();
        var course = _context.Courses.First();
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        });
        _context.SaveChanges();

        // Act
        var result = _controller.Index(instructor.ID, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var viewModel = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(viewModel.Courses);
        Assert.Single(viewModel.Courses);
    }

    // ---- Details Tests ----

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructorId = _context.Instructors.First().ID;

        // Act
        var result = _controller.Details(instructorId) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    // ---- Create Tests ----

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(instructor.CourseAssignments);
    }

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null!) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(2, _context.Instructors.Count());
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };
        var selectedCourses = new[] { "1050" };

        // Act
        var result = _controller.Create(instructor, selectedCourses) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var savedInstructor = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.LastName == "Doe");
        Assert.Single(savedInstructor.CourseAssignments);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        // Arrange
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null!) as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    // ---- Delete Tests ----

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructorId = _context.Instructors.First().ID;

        // Act
        var result = _controller.Delete(instructorId) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructorId, instructor.ID);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        // Arrange
        var instructor = _context.Instructors.First();

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Empty(_context.Instructors);
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDepartmentAdmin_ClearsDepartmentInstructor()
    {
        // Arrange
        var instructor = _context.Instructors.First();
        var dept = _context.Departments.First();
        dept.InstructorID = instructor.ID;
        _context.SaveChanges();

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        var updatedDept = _context.Departments.First();
        Assert.Null(updatedDept.InstructorID);
    }

    // ---- Edit Tests ----

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit((int?)null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructorId = _context.Instructors.First().ID;

        // Act
        var result = _controller.Edit((int?)instructorId) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }
}

