using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextHelper.CreateSeededContext();
        _controller = CreateController(_context);
        // Drain any leftover notifications
        var svc = new ContosoUniversity.Services.NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    private static NotificationsController CreateController(SchoolContext context)
    {
        var controller = new NotificationsController(context);
        controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        controller.TempData = new TempDataDictionary(
            controller.ControllerContext.HttpContext,
            new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        return controller;
    }

    public void Dispose()
    {
        // Drain notifications
        var svc = new ContosoUniversity.Services.NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithNoNotifications()
    {
        // Act
        var result = _controller.GetNotifications();

        // Assert
        Assert.NotNull(result);
        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Arrange - enqueue a notification via the service
        var svc = new ContosoUniversity.Services.NotificationService();
        svc.SendNotification("Student", "1", "John", EntityOperation.CREATE);

        // Act
        var result = _controller.GetNotifications();

        // Assert
        Assert.NotNull(result);
        Assert.IsType<JsonResult>(result);
        svc.Dispose();
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
        // Act
        var result = _controller.MarkAsRead(1);

        // Assert
        Assert.NotNull(result);
        Assert.IsType<JsonResult>(result);
    }

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class ModelTests
{
    // ---- Person / Student / Instructor ----

    [Fact]
    public void Person_FullName_ReturnsConcatenatedName()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander"
        };

        // Act
        var fullName = student.FullName;

        // Assert
        Assert.Equal("Alexander, Carson", fullName);
    }

    [Fact]
    public void Instructor_FullName_ReturnsConcatenatedName()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie"
        };

        // Act & Assert
        Assert.Equal("Abercrombie, Kim", instructor.FullName);
    }

    // ---- ErrorViewModel ----

    [Fact]
    public void ErrorViewModel_ShowRequestId_TrueWhenSet()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = "abc123" };

        // Assert
        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenNull()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = null };

        // Assert
        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenEmpty()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = "" };

        // Assert
        Assert.False(model.ShowRequestId);
    }

    // ---- Course Properties ----

    [Fact]
    public void Course_Properties_SetCorrectly()
    {
        // Arrange & Act
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/path/to/image.jpg"
        };

        // Assert
        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(1, course.DepartmentID);
        Assert.Equal("/path/to/image.jpg", course.TeachingMaterialImagePath);
    }

    // ---- Department Properties ----

    [Fact]
    public void Department_Properties_SetCorrectly()
    {
        // Arrange & Act
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = 5
        };

        // Assert
        Assert.Equal(1, dept.DepartmentID);
        Assert.Equal("Engineering", dept.Name);
        Assert.Equal(350000m, dept.Budget);
        Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
        Assert.Equal(5, dept.InstructorID);
    }

    [Fact]
    public void Department_InstructorID_CanBeNull()
    {
        // Arrange & Act
        var dept = new Department { InstructorID = null };

        // Assert
        Assert.Null(dept.InstructorID);
    }

    // ---- Enrollment Properties ----

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        // Arrange & Act
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 1050,
            StudentID = 1,
            Grade = null
        };

        // Assert
        Assert.Null(enrollment.Grade);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Enrollment_Grade_AcceptsAllGradeValues(Grade grade)
    {
        // Arrange & Act
        var enrollment = new Enrollment { Grade = grade };

        // Assert
        Assert.Equal(grade, enrollment.Grade);
    }

    // ---- Notification Properties ----

    [Fact]
    public void Notification_Properties_SetCorrectly()
    {
        // Arrange
        var now = DateTime.Now;
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "New Student created",
            CreatedAt = now,
            CreatedBy = "Admin",
            IsRead = false,
            ReadAt = null
        };

        // Assert
        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student created", notification.Message);
        Assert.Equal(now, notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    // ---- EntityOperation Enum ----

    [Fact]
    public void EntityOperation_HasExpectedValues()
    {
        // Assert
        Assert.Equal(0, (int)EntityOperation.CREATE);
        Assert.Equal(1, (int)EntityOperation.UPDATE);
        Assert.Equal(2, (int)EntityOperation.DELETE);
    }

    // ---- CourseAssignment ----

    [Fact]
    public void CourseAssignment_Properties_SetCorrectly()
    {
        // Arrange & Act
        var ca = new CourseAssignment
        {
            InstructorID = 1,
            CourseID = 1050
        };

        // Assert
        Assert.Equal(1, ca.InstructorID);
        Assert.Equal(1050, ca.CourseID);
    }

    // ---- OfficeAssignment ----

    [Fact]
    public void OfficeAssignment_Properties_SetCorrectly()
    {
        // Arrange & Act
        var oa = new OfficeAssignment
        {
            InstructorID = 1,
            Location = "Smith 17"
        };

        // Assert
        Assert.Equal(1, oa.InstructorID);
        Assert.Equal("Smith 17", oa.Location);
    }
}

