    {
        // Arrange & Act
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 1050,
            StudentID = 1,
            Grade = null
        };

        // Assert
        Assert.Null(enrollment.Grade);
    }

    [Theory]
